/**
 * Core types shared across SAGE modules
 */

import { z } from 'zod';

// ============================================
// Configuration
// ============================================

export const SubagentSchema = z.object({
  name: z.string(),
  description: z.string(),
  systemPrompt: z.string(),
  toolNames: z.array(z.string()).optional(),
  mcpServers: z.array(z.string()).optional(),
  model: z.string().optional(),
  temperature: z.number().optional(),
  maxTokens: z.number().optional(),
  maxDepth: z.number().optional(),
});

export type SubagentConfig = z.infer<typeof SubagentSchema>;

export const SageConfigSchema = z.object({
  // Agent configuration
  agent: z.object({
    name: z.string().optional(),
    systemPrompt: z.string().optional(),
    maxDepth: z.number().optional(),
    toolTimeout: z.number().optional(),
    maxToolResultSize: z.number().optional(),
  }).optional(),

  // Provider configuration
  provider: z.object({
    apiKey: z.string().optional(),
    baseUrl: z.string().optional(),
  }).optional(),

  // Model configuration
  model: z.string().optional(),
  temperature: z.number().optional(),
  maxTokens: z.number().optional(),
  parallelToolCalls: z.boolean().optional(), // Enable parallel tool calling (default: true)

  // Streaming configuration
  streaming: z.discriminatedUnion('type', [
    z.object({
      type: z.literal('redis'),
      url: z.string(),
      keyPrefix: z.string().optional(),
      ttl: z.number().optional(),
    }),
    z.object({
      type: z.literal('memory'),
    }),
  ]).optional(),

  // Database configuration
  database: z.discriminatedUnion('type', [
    z.object({
      type: z.literal('convex'),
      url: z.string(),
    }),
    z.object({
      type: z.literal('memory'),
    }),
  ]).optional(),

  // Auth configuration
  auth: z.object({
    databaseUrl: z.string(),
  }).optional(),

  // Tools
  tools: z.array(z.any()).optional(),

  // Subagent configuration
  subagents: z.array(SubagentSchema).optional(),
  maxAgentDepth: z.number().optional(),

  // Context/memory configuration
  context: z.object({
    enabled: z.boolean().optional(),
    model: z.string().optional(),
    contextWindow: z.number().optional(),
    maxResponseTokens: z.number().optional(),
    summary: z.object({
      enabled: z.boolean().optional(),
      model: z.string().optional(),
      targetTokens: z.number().optional(),
    }).optional(),
    workingMemory: z.object({
      enabled: z.boolean().optional(),
      autoExtract: z.boolean().optional(),
      extractionModel: z.string().optional(),
      maxMemoriesInPrompt: z.number().optional(),
    }).optional(),
    decay: z.object({
      enabled: z.boolean().optional(),
      halfLifeDays: z.number().optional(),
      minConfidence: z.number().optional(),
    }).optional(),
  }).optional(),

  // Lifecycle hooks (not validated by Zod - just type-checked)
  hooks: z.any().optional(),

  // Retry configuration (not validated by Zod - just type-checked)
  retry: z.any().optional(),
});

import type { RetryConfig } from './utils/retry';

export type SageConfig = z.infer<typeof SageConfigSchema> & {
  /** Lifecycle hooks for observing and intercepting the agentic loop */
  hooks?: SAGEHooks;
  /** Retry configuration for LLM API calls */
  retry?: RetryConfig;
};

// Default values applied at runtime
export const DEFAULT_CONFIG = {
  agent: {
    maxDepth: 10,
    toolTimeout: 30000,
    maxToolResultSize: 50000,
  },
  model: 'gpt-4o',
  temperature: 0.7,
  maxTokens: 4096,
  streaming: {
    keyPrefix: 'sage:stream:',
    ttl: 3600,
  },
} as const;

// ============================================
// Messages
// ============================================

export interface Message {
  role: 'user' | 'assistant' | 'tool' | 'system';
  content: string | ContentPart[];
  toolCalls?: ToolCall[];
  toolCallId?: string;
  reasoning?: string;
}

export interface ContentPart {
  type: 'text' | 'image' | 'file';
  text?: string;
  imageUrl?: string;
  fileUrl?: string;
}

export interface ToolCall {
  id: string;
  type: 'function';
  function: {
    name: string;
    arguments: string;
  };
  status?: 'pending' | 'running' | 'completed' | 'failed';
  result?: string;
}

// ============================================
// Session
// ============================================

export type SessionStatus =
  | 'pending'
  | 'running'
  | 'tool_loop'
  | 'completed'
  | 'failed'
  | 'cancelled';

export interface Session {
  id: string;
  conversationId: string;
  userId: string;
  streamId: string;
  status: SessionStatus;
  toolLoopDepth: number;
  createdAt: number;
  completedAt?: number;
  error?: string;
}

// ============================================
// Streaming
// ============================================

export type StreamChunkType =
  | 'token'
  | 'reasoning'
  | 'tool_call'
  | 'tool_result'
  | 'status'
  | 'error'
  | 'subagent_start'
  | 'subagent_end';

export interface StreamChunk {
  type: StreamChunkType;
  content: string;
  timestamp: number;
  toolCallId?: string;
  toolName?: string;
  toolArguments?: string;
  status?: SessionStatus;
  agentId?: string;
  agentDepth?: number;
}

export interface StreamEntry {
  id: string;
  data: StreamChunk;
}

// ============================================
// Agent Result
// ============================================

export interface AgentResult {
  content: string;
  reasoning?: string;
  toolCalls: ToolCall[];
  inputTokens: number;
  outputTokens: number;
}

// ============================================
// Lifecycle Hooks
// ============================================

/**
 * Context passed to lifecycle hooks
 */
export interface HookContext {
  /** Session ID */
  sessionId: string;
  /** Conversation ID */
  conversationId: string;
  /** User ID */
  userId: string;
  /** Stream ID */
  streamId: string;
  /** Agent ID (root or subagent name) */
  agentId: string;
  /** Agent nesting depth */
  agentDepth: number;
  /** Current messages */
  messages: Message[];
}

/**
 * LLM response information passed to afterLLMCall hook
 */
export interface LLMResponse {
  /** Response content */
  content: string;
  /** Reasoning content if any */
  reasoning?: string;
  /** Tool calls if any */
  toolCalls: ToolCall[];
  /** Input tokens used */
  inputTokens: number;
  /** Output tokens used */
  outputTokens: number;
}

/**
 * Tool information for hooks
 */
export interface ToolInfo {
  /** Tool name */
  name: string;
  /** Tool description */
  description: string;
}

/**
 * Lifecycle hooks for observing and intercepting the agentic loop.
 * All hooks are optional and async.
 */
export interface SAGEHooks {
  /**
   * Called before sending a request to the LLM.
   * Use for logging, metrics, or request modification.
   */
  beforeLLMCall?: (context: HookContext) => Promise<void>;

  /**
   * Called after receiving a response from the LLM.
   * Use for logging, metrics, or response analysis.
   */
  afterLLMCall?: (context: HookContext, response: LLMResponse) => Promise<void>;

  /**
   * Called before executing a tool.
   * Return modified args to change the input, or throw to prevent execution.
   * @returns Modified arguments (or original if unchanged)
   */
  beforeToolExecution?: (
    tool: ToolInfo,
    args: Record<string, unknown>,
    context: HookContext
  ) => Promise<Record<string, unknown>>;

  /**
   * Called after a tool execution completes (success or failure).
   * Use for logging, metrics, or result analysis.
   */
  afterToolExecution?: (
    tool: ToolInfo,
    args: Record<string, unknown>,
    result: unknown,
    error: Error | null,
    context: HookContext
  ) => Promise<void>;

  /**
   * Called when any error occurs in the agentic loop.
   * Use for error reporting (e.g., Sentry).
   */
  onError?: (error: Error, context: HookContext) => Promise<void>;

  /**
   * Called when the agent completes successfully.
   * Use for final logging, metrics, or cleanup.
   */
  onComplete?: (result: AgentResult, context: HookContext) => Promise<void>;

  /**
   * Called when a subagent starts execution.
   */
  onSubagentStart?: (
    agentId: string,
    task: string,
    context: HookContext
  ) => Promise<void>;

  /**
   * Called when a subagent completes execution.
   */
  onSubagentEnd?: (
    agentId: string,
    result: string,
    context: HookContext
  ) => Promise<void>;
}

// ============================================
// Utility function
// ============================================

/**
 * Define a SAGE configuration.
 * Validation is deferred to runtime to support build-time imports.
 */
export function defineConfig(config: SageConfig): SageConfig {
  // Don't validate at import time - defer to runtime
  // This allows the config to be imported during Next.js build
  // even if environment variables aren't set
  return config;
}

/**
 * Validate and apply defaults to a SAGE configuration.
 * Call this at runtime before using the config.
 */
export function validateConfig(config: SageConfig): SageConfig {
  return SageConfigSchema.parse(config);
}
