/**
 * Working Memory Manager
 *
 * Cross-conversation persistent memory for SAGE agents.
 * Learns facts, preferences, and context from conversations
 * and injects relevant memories into future interactions.
 *
 * Supports:
 * - Automatic memory extraction after each turn
 * - Semantic search (with embeddings + vector store)
 * - Keyword fallback search (without embeddings)
 * - Memory decay (unused memories lose confidence)
 * - remember/recall tools for explicit agent memory
 */

import { randomUUID } from 'crypto';
import type { Message } from '../types';
import type {
  MemoryEntry,
  MemoryStore,
  EmbeddingsAdapter,
  VectorStore,
  WorkingMemoryManager,
  WorkingMemoryConfig,
} from './types';
import { retrieveMemories } from './retrieval';

/**
 * Create a working memory manager.
 *
 * @example
 * ```typescript
 * const memory = createWorkingMemory({
 *   enabled: true,
 *   autoExtract: true,
 *   store: new InMemoryStore(),
 *   embeddings: myEmbeddingsAdapter,
 *   vectorStore: new QdrantVectorStore({ ... }),
 *   provider: { apiKey: '...', baseUrl: '...' },
 * });
 * ```
 */
export function createWorkingMemory(config: WorkingMemoryConfig): WorkingMemoryManager {
  const {
    store,
    embeddings,
    vectorStore,
    maxMemoriesInPrompt = 20,
    provider,
    extractionModel,
  } = config;

  const hasSemanticSearch = !!(embeddings && vectorStore);

  return {
    /**
     * Get relevant memories formatted for system prompt injection.
     */
    async getContextForPrompt(userId: string, currentMessages: Message[]): Promise<string> {
      const queryText = extractQueryContext(currentMessages);
      if (!queryText) {
        // Just return recent memories
        const recent = await store.listByUser(userId, { limit: maxMemoriesInPrompt });
        if (recent.length === 0) return '';
        return formatMemoriesForPrompt(recent);
      }

      // Use the advanced retrieval pipeline
      const memories = await retrieveMemories(queryText, userId, {
        finalLimit: maxMemoriesInPrompt,
      }, {
        memory: store,
        embeddings,
        vector: vectorStore,
      });

      if (memories.length === 0) return '';

      // Update lastAccessedAt and accessCount for retrieved memories (reinforcement)
      const now = Date.now();
      for (const mem of memories) {
        mem.lastAccessedAt = now;
        mem.accessCount = (mem.accessCount ?? 0) + 1;
        mem.confidence = Math.min(1, mem.confidence + 0.05);
        store.save(mem).catch(() => {}); // Fire-and-forget
      }

      // Format memories for injection
      return formatMemoriesForPrompt(memories);
    },

    /**
     * Extract new memories from a conversation turn using LLM.
     */
    async extractMemories(
      userId: string,
      messages: Message[],
      assistantResponse: string,
      conversationId?: string,
    ): Promise<MemoryEntry[]> {
      if (!provider) return [];

      const model = extractionModel || 'gpt-4o';

      // Get the last few messages for context
      const recentMessages = messages.slice(-6);
      const conversationSnippet = recentMessages
        .map(m => {
          const role = m.role;
          const content = typeof m.content === 'string' ? m.content : '[multimodal]';
          return `${role}: ${content.slice(0, 300)}`;
        })
        .join('\n');

      const prompt = `Analyze this conversation snippet and extract any facts, preferences, or important context worth remembering long-term.

Conversation:
---
${conversationSnippet}
assistant: ${assistantResponse.slice(0, 500)}
---

Return a JSON array of memories to save. Each memory should have:
- "content": string — the fact/preference/context to remember
- "category": "fact" | "preference" | "instruction" | "context"
- "confidence": number 0.0-1.0 — how certain this information is
- "memoryType": "episodic" (event/experience) | "semantic" (general fact) | "procedural" (how-to/instruction)
- "importance": number 0.0-1.0 — how important this is to the user
- "persistenceLevel": "ephemeral" (temporary, low confidence) | "shortTerm" (moderate) | "longTerm" (user-stated, high confidence)
- "entities": string[] — people, places, organizations, dates, or concepts mentioned
- "eventTime": number | null — Unix timestamp if the memory references a specific date/time, null otherwise
- "expiresAt": number | null — Unix timestamp if the memory is time-sensitive (e.g. "quiz next Wednesday"), null otherwise

Rules:
- Only extract genuinely useful long-term information
- Don't extract transient information (timestamps, temporary states)
- Prefer user-stated facts over inferred ones
- User-explicit info → "longTerm", inferred → "shortTerm", uncertain → "ephemeral"
- Return [] if nothing worth remembering

Return ONLY the JSON array, no explanation.`;

      try {
        const response = await fetch(`${provider.baseUrl}/responses`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${provider.apiKey}`,
            'OpenAI-Beta': 'responses=v1',
          },
          body: JSON.stringify({
            model,
            input: [{ role: 'user', content: prompt }],
            max_output_tokens: 500,
            temperature: 0.2,
            stream: false,
          }),
        });

        if (!response.ok) return [];

        const data = await response.json() as { output_text?: string };
        if (!data.output_text) return [];

        // Parse the JSON array
        const raw = parseJSONFromLLM(data.output_text);
        if (!Array.isArray(raw)) return [];

        const now = Date.now();
        const entries: MemoryEntry[] = [];

        for (const item of raw) {
          if (!item.content || typeof item.content !== 'string') continue;

          const entry: MemoryEntry = {
            id: randomUUID(),
            userId,
            content: item.content,
            category: validateCategory(item.category),
            source: 'agent',
            confidence: Math.max(0, Math.min(1, Number(item.confidence) || 0.7)),
            createdAt: now,
            lastAccessedAt: now,
            conversationId,
            // Hierarchical fields
            memoryType: validateMemoryType(item.memoryType),
            importance: typeof item.importance === 'number' ? Math.max(0, Math.min(1, item.importance)) : undefined,
            persistenceLevel: validatePersistenceLevel(item.persistenceLevel),
            entities: Array.isArray(item.entities) ? item.entities.filter((e: unknown) => typeof e === 'string') : undefined,
            eventTime: typeof item.eventTime === 'number' ? item.eventTime : undefined,
            expiresAt: typeof item.expiresAt === 'number' ? item.expiresAt : undefined,
            version: 1,
            accessCount: 0,
          };

          // Generate embedding if adapter available
          if (embeddings) {
            try {
              entry.embedding = await embeddings.embed(entry.content);
            } catch {
              // Continue without embedding
            }
          }

          // Save to store
          await store.save(entry);

          // Save to vector store if available
          if (vectorStore && entry.embedding) {
            try {
              await vectorStore.upsert([{
                id: entry.id,
                vector: entry.embedding,
                metadata: {
                  userId: entry.userId,
                  category: entry.category,
                  confidence: entry.confidence,
                  content: entry.content,
                },
              }]);
            } catch {
              // Continue without vector store
            }
          }

          entries.push(entry);
        }

        return entries;
      } catch (error) {
        console.warn('[WorkingMemory] Extraction failed:', error);
        return [];
      }
    },

    /**
     * Explicit save — for "remember" tool
     */
    async remember(
      userId: string,
      content: string,
      category?: MemoryEntry['category'],
      conversationId?: string,
    ): Promise<MemoryEntry> {
      const now = Date.now();
      const entry: MemoryEntry = {
        id: randomUUID(),
        userId,
        content,
        category: category || 'fact',
        source: 'user',
        confidence: 1.0, // User-stated = maximum confidence
        createdAt: now,
        lastAccessedAt: now,
        conversationId,
        // User-explicit memories get longTerm persistence
        memoryType: 'semantic',
        importance: 1.0,
        persistenceLevel: 'longTerm',
        version: 1,
        accessCount: 0,
      };

      // Generate embedding
      if (embeddings) {
        try {
          entry.embedding = await embeddings.embed(content);
        } catch {
          // Continue without embedding
        }
      }

      // Save to both stores
      await store.save(entry);

      if (vectorStore && entry.embedding) {
        try {
          await vectorStore.upsert([{
            id: entry.id,
            vector: entry.embedding,
            metadata: {
              userId,
              category: entry.category,
              confidence: entry.confidence,
              content,
            },
          }]);
        } catch {
          // Continue without vector
        }
      }

      return entry;
    },

    /**
     * Explicit recall — for "recall" tool
     */
    async recall(userId: string, query: string, limit: number = 10): Promise<MemoryEntry[]> {
      // Use the advanced retrieval pipeline
      const memories = await retrieveMemories(query, userId, {
        finalLimit: limit,
      }, {
        memory: store,
        embeddings,
        vector: vectorStore,
      });

      // Access reinforcement (fire-and-forget)
      const now = Date.now();
      for (const mem of memories) {
        mem.lastAccessedAt = now;
        mem.accessCount = (mem.accessCount ?? 0) + 1;
        mem.confidence = Math.min(1, mem.confidence + 0.05);
        store.save(mem).catch(() => {});
      }

      return memories;
    },

    /**
     * Prune old or low-confidence memories
     */
    async prune(userId: string, options?: {
      maxAge?: number;
      minConfidence?: number;
    }): Promise<number> {
      const maxAge = options?.maxAge ?? 90 * 24 * 60 * 60 * 1000; // 90 days
      const minConfidence = options?.minConfidence ?? 0.3;
      const now = Date.now();

      const allMemories = await store.listByUser(userId);
      const toDelete: string[] = [];

      for (const mem of allMemories) {
        const age = now - mem.lastAccessedAt;
        const isStale = age > maxAge;
        const isLowConfidence = mem.confidence < minConfidence;

        // Delete if stale AND low confidence, or if extremely old
        if ((isStale && isLowConfidence) || age > maxAge * 3) {
          toDelete.push(mem.id);
        }
      }

      // Delete from both stores
      for (const id of toDelete) {
        await store.delete(id);
      }

      if (vectorStore && toDelete.length > 0) {
        try {
          await vectorStore.delete(toDelete);
        } catch {
          // Continue
        }
      }

      return toDelete.length;
    },
  };
}

// ============================================
// Helpers
// ============================================

/**
 * Extract query context from recent messages for semantic search
 */
function extractQueryContext(messages: Message[]): string {
  const recent = messages.slice(-3);
  const parts: string[] = [];

  for (const msg of recent) {
    if (msg.role === 'user') {
      const content = typeof msg.content === 'string'
        ? msg.content
        : (msg.content?.map(p => p.type === 'text' ? p.text : '').join(' ') || '');
      if (content) parts.push(content.slice(0, 200));
    }
  }

  return parts.join(' ').trim();
}

/**
 * Keyword-based fallback search when no embeddings/vector store
 */
async function keywordFallback(
  store: MemoryStore,
  userId: string,
  messages: Message[],
  limit: number,
): Promise<MemoryEntry[]> {
  const queryText = extractQueryContext(messages);
  if (!queryText) {
    // Just return recent memories
    return store.listByUser(userId, { limit });
  }
  return store.search(userId, queryText, limit);
}

/**
 * Format memories for system prompt injection
 */
function formatMemoriesForPrompt(memories: MemoryEntry[]): string {
  if (memories.length === 0) return '';

  const lines = memories.map(m => {
    const prefix = m.source === 'user' ? '' : '(inferred) ';
    return `- ${prefix}${m.content}`;
  });

  return `## User Context (from memory)\n${lines.join('\n')}`;
}

/**
 * Validate memory category
 */
function validateCategory(cat: unknown): MemoryEntry['category'] {
  const valid = ['fact', 'preference', 'instruction', 'context'];
  if (typeof cat === 'string' && valid.includes(cat)) {
    return cat as MemoryEntry['category'];
  }
  return 'fact';
}

/**
 * Validate memory type
 */
function validateMemoryType(type: unknown): MemoryEntry['memoryType'] {
  const valid = ['episodic', 'semantic', 'procedural', 'working'];
  if (typeof type === 'string' && valid.includes(type)) {
    return type as MemoryEntry['memoryType'];
  }
  return undefined;
}

/**
 * Validate persistence level
 */
function validatePersistenceLevel(level: unknown): MemoryEntry['persistenceLevel'] {
  const valid = ['ephemeral', 'shortTerm', 'longTerm'];
  if (typeof level === 'string' && valid.includes(level)) {
    return level as MemoryEntry['persistenceLevel'];
  }
  return undefined;
}

/**
 * Parse JSON from LLM output (handles markdown code blocks, extra text, etc.)
 */
function parseJSONFromLLM(text: string): unknown {
  // Try direct parse first
  try {
    return JSON.parse(text);
  } catch {
    // Look for JSON array in code block
    const match = text.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
    if (match) {
      try {
        return JSON.parse(match[1]);
      } catch {
        // Continue
      }
    }

    // Look for JSON array anywhere in text
    const arrayMatch = text.match(/\[[\s\S]*\]/);
    if (arrayMatch) {
      try {
        return JSON.parse(arrayMatch[0]);
      } catch {
        // Continue
      }
    }

    return null;
  }
}
