/**
 * Subagent Module
 *
 * Enables parent agents to delegate tasks to child agents.
 * Each subagent runs its own processWithToolLoop with isolated
 * tools, system prompt, and message history but writes to the
 * same stream with agentId/agentDepth attribution.
 */

import type { SubagentConfig } from '../types';
import type { Tool, ToolRegistry } from '../tools/types';
import type { AgentContext } from './types';
import { createToolRegistry } from '../tools/registry';
import { processWithToolLoop } from './loop';

/**
 * Subagent definition — mirrors SubagentConfig but kept as a
 * plain interface for use in non-Zod contexts.
 */
export interface SubagentDefinition {
  name: string;
  description: string;
  systemPrompt: string;
  toolNames?: string[];
  mcpServers?: string[];
  model?: string;
  temperature?: number;
  maxTokens?: number;
  maxDepth?: number;
}

/**
 * Create a delegation tool for a single subagent definition.
 *
 * The returned Tool, when executed, spins up a child agent loop
 * that writes to the same stream as the parent.
 */
export function createSubagentTool(
  definition: SubagentDefinition,
  parentContext: AgentContext,
  allTools: Tool[],
  maxAgentDepth: number,
  allDefinitions: SubagentDefinition[],
): Tool {
  return {
    name: `delegate_to_${definition.name}`,
    description: definition.description,
    parameters: {
      type: 'object',
      properties: {
        task: {
          type: 'string',
          description: 'The task to delegate to this agent',
        },
      },
      required: ['task'],
    },
    execute: async (args) => {
      const task = args.task as string;
      const childDepth = parentContext.agentDepth + 1;

      // Emit subagent_start
      await parentContext.streamStore.append(parentContext.streamId, {
        type: 'subagent_start',
        content: task,
        timestamp: Date.now(),
        agentId: definition.name,
        agentDepth: childDepth,
      });

      parentContext.callbacks?.onSubagentStart?.(definition.name, task);

      try {
        // Build child tool registry with only the allowed tools
        const childRegistry = createToolRegistry();

        if (definition.toolNames && definition.toolNames.length > 0) {
          for (const toolName of definition.toolNames) {
            const tool = allTools.find(t => t.name === toolName);
            if (tool) {
              childRegistry.register(tool);
            }
          }
        }

        // Register MCP servers on child if configured
        if (definition.mcpServers) {
          for (const serverUrl of definition.mcpServers) {
            await childRegistry.registerMCP(serverUrl);
          }
        }

        // Build child context — shares streamStore and streamId
        const childConfig = {
          ...parentContext.config,
          ...(definition.model && { model: definition.model }),
          ...(definition.temperature !== undefined && { temperature: definition.temperature }),
          ...(definition.maxTokens !== undefined && { maxTokens: definition.maxTokens }),
          ...(definition.maxDepth !== undefined && { agent: { ...parentContext.config.agent, maxDepth: definition.maxDepth } }),
        };

        const childContext: AgentContext = {
          sessionId: parentContext.sessionId,
          conversationId: parentContext.conversationId,
          userId: parentContext.userId,
          streamId: parentContext.streamId,
          systemPrompt: definition.systemPrompt,
          messages: [{ role: 'user', content: task }],
          tools: childRegistry,
          streamStore: parentContext.streamStore,
          config: childConfig,
          callbacks: parentContext.callbacks,
          agentId: definition.name,
          agentDepth: childDepth,
        };

        // If child is still below max depth, register subagent tools on it too
        registerSubagentTools(
          childRegistry,
          allDefinitions,
          childContext,
          allTools,
          maxAgentDepth,
        );

        // Run the child agent loop
        const result = await processWithToolLoop(childContext);

        // Emit subagent_end
        await parentContext.streamStore.append(parentContext.streamId, {
          type: 'subagent_end',
          content: result.content,
          timestamp: Date.now(),
          agentId: definition.name,
          agentDepth: childDepth,
        });

        parentContext.callbacks?.onSubagentEnd?.(definition.name, result.content);

        return result.content;
      } catch (error) {
        const errorMsg = error instanceof Error ? error.message : String(error);

        // Always emit subagent_end even on failure
        await parentContext.streamStore.append(parentContext.streamId, {
          type: 'subagent_end',
          content: JSON.stringify({ error: true, message: errorMsg }),
          timestamp: Date.now(),
          agentId: definition.name,
          agentDepth: childDepth,
        });

        parentContext.callbacks?.onSubagentEnd?.(
          definition.name,
          JSON.stringify({ error: true, message: errorMsg }),
        );

        throw error;
      }
    },
  };
}

/**
 * Register delegation tools for all subagent definitions on a registry.
 *
 * If the parent is already at or beyond maxAgentDepth, no tools are
 * registered (preventing further nesting).
 */
export function registerSubagentTools(
  registry: ToolRegistry,
  definitions: SubagentDefinition[],
  parentContext: AgentContext,
  allTools: Tool[],
  maxAgentDepth: number,
): void {
  if (parentContext.agentDepth >= maxAgentDepth) {
    return;
  }

  for (const def of definitions) {
    const tool = createSubagentTool(def, parentContext, allTools, maxAgentDepth, definitions);
    registry.register(tool);
  }
}
