/**
 * JWT Authentication with jose
 *
 * Proper JWT verification with support for RS256, ES256, HS256.
 * Uses the jose library for cryptographic operations.
 */

import * as jose from 'jose';
import type { JWTPayload } from './types';

/**
 * JWT verification options
 */
export interface JWTVerifyOptions {
  /** Expected issuer */
  issuer?: string;

  /** Expected audience */
  audience?: string;

  /** Algorithms to accept */
  algorithms?: string[];

  /** Clock tolerance in seconds */
  clockTolerance?: number;

  /** Maximum token age in seconds */
  maxTokenAge?: number;
}

/**
 * JWT signing options
 */
export interface JWTSignOptions {
  /** Issuer claim */
  issuer?: string;

  /** Audience claim */
  audience?: string;

  /** Expiration time in seconds from now */
  expiresIn?: number;

  /** Not before time in seconds from now */
  notBefore?: number;

  /** JWT ID */
  jti?: string;
}

/**
 * Result of JWT verification
 */
export interface JWTVerifyResult {
  /** Whether verification succeeded */
  valid: boolean;

  /** Decoded payload if valid */
  payload?: JWTPayload;

  /** Error message if invalid */
  error?: string;
}

/**
 * Key types for JWT operations
 */
export type JWTKey = 
  | { type: 'secret'; value: string | Uint8Array }
  | { type: 'jwks'; url: string }
  | { type: 'publicKey'; value: string }
  | { type: 'privateKey'; value: string };

/**
 * Create a JWT verifier
 */
export function createJWTVerifier(
  key: JWTKey,
  options?: JWTVerifyOptions
) {
  const opts = {
    algorithms: ['RS256', 'ES256', 'HS256'] as string[],
    clockTolerance: 60,
    ...options,
  };

  return {
    /**
     * Verify a JWT token
     */
    async verify(token: string): Promise<JWTVerifyResult> {
      try {
        let verifyKey: Awaited<ReturnType<typeof jose.importSPKI>> | Uint8Array;

        switch (key.type) {
          case 'secret':
            verifyKey = typeof key.value === 'string' 
              ? new TextEncoder().encode(key.value)
              : key.value;
            break;

          case 'jwks': {
            const JWKS = jose.createRemoteJWKSet(new URL(key.url));
            const { payload } = await jose.jwtVerify(token, JWKS, {
              issuer: opts.issuer,
              audience: opts.audience,
              clockTolerance: opts.clockTolerance,
              maxTokenAge: opts.maxTokenAge ? `${opts.maxTokenAge}s` : undefined,
            });
            return { valid: true, payload: payload as JWTPayload };
          }

          case 'publicKey':
            verifyKey = await jose.importSPKI(key.value, opts.algorithms[0] || 'RS256');
            break;

          case 'privateKey':
            verifyKey = await jose.importPKCS8(key.value, opts.algorithms[0] || 'RS256');
            break;

          default:
            return { valid: false, error: 'Invalid key type' };
        }

        const { payload } = await jose.jwtVerify(token, verifyKey, {
          issuer: opts.issuer,
          audience: opts.audience,
          clockTolerance: opts.clockTolerance,
          maxTokenAge: opts.maxTokenAge ? `${opts.maxTokenAge}s` : undefined,
        });

        return { valid: true, payload: payload as JWTPayload };
      } catch (error) {
        if (error instanceof jose.errors.JWTExpired) {
          return { valid: false, error: 'Token expired' };
        }
        if (error instanceof jose.errors.JWTClaimValidationFailed) {
          return { valid: false, error: `Claim validation failed: ${error.message}` };
        }
        if (error instanceof jose.errors.JWSSignatureVerificationFailed) {
          return { valid: false, error: 'Invalid signature' };
        }
        return {
          valid: false,
          error: error instanceof Error ? error.message : 'Token verification failed',
        };
      }
    },
  };
}

/**
 * Create a JWT signer
 */
export function createJWTSigner(
  key: JWTKey,
  algorithm: string = 'HS256'
) {
  return {
    /**
     * Sign a payload to create a JWT
     */
    async sign(
      payload: Record<string, unknown>,
      options?: JWTSignOptions
    ): Promise<string> {
      let signKey: Awaited<ReturnType<typeof jose.importPKCS8>> | Uint8Array;

      switch (key.type) {
        case 'secret':
          signKey = typeof key.value === 'string'
            ? new TextEncoder().encode(key.value)
            : key.value;
          break;

        case 'privateKey':
          signKey = await jose.importPKCS8(key.value, algorithm);
          break;

        default:
          throw new Error('Cannot sign with JWKS or public key');
      }

      const jwt = new jose.SignJWT(payload as jose.JWTPayload)
        .setProtectedHeader({ alg: algorithm });

      if (options?.issuer) {
        jwt.setIssuer(options.issuer);
      }

      if (options?.audience) {
        jwt.setAudience(options.audience);
      }

      if (options?.expiresIn) {
        // Handle negative expiration (already expired tokens) by setting exp directly
        if (options.expiresIn < 0) {
          const expTime = Math.floor(Date.now() / 1000) + options.expiresIn;
          jwt.setExpirationTime(expTime);
        } else {
          jwt.setExpirationTime(`${options.expiresIn}s`);
        }
      }

      if (options?.notBefore) {
        jwt.setNotBefore(`${options.notBefore}s`);
      }

      if (options?.jti) {
        jwt.setJti(options.jti);
      }

      jwt.setIssuedAt();

      return jwt.sign(signKey);
    },
  };
}

/**
 * Decode a JWT without verification (for debugging)
 */
export function decodeJWT(token: string): JWTPayload | null {
  try {
    const decoded = jose.decodeJwt(token);
    return decoded as JWTPayload;
  } catch {
    return null;
  }
}

/**
 * Verify a JWT with a simple secret (convenience function)
 */
export async function verifyJWT(
  token: string,
  secret: string,
  options?: JWTVerifyOptions
): Promise<JWTVerifyResult> {
  const verifier = createJWTVerifier({ type: 'secret', value: secret }, options);
  return verifier.verify(token);
}

/**
 * Sign a JWT with a simple secret (convenience function)
 */
export async function signJWT(
  payload: Record<string, unknown>,
  secret: string,
  options?: JWTSignOptions
): Promise<string> {
  const signer = createJWTSigner({ type: 'secret', value: secret });
  return signer.sign(payload, options);
}

/**
 * Create a JWKS verifier from a URL
 */
export function createJWKSVerifier(
  jwksUrl: string,
  options?: JWTVerifyOptions
) {
  return createJWTVerifier({ type: 'jwks', url: jwksUrl }, options);
}
