/**
 * Base Transport
 *
 * Abstract base class for MCP transports.
 */

import type {
  MCPTransport,
  JSONRPCMessage,
  JSONRPCRequest,
  JSONRPCNotification,
} from '../types';

/**
 * Abstract base transport with common functionality
 */
export abstract class BaseTransport implements MCPTransport {
  protected messageHandler: ((message: JSONRPCMessage) => void) | null = null;
  protected errorHandler: ((error: Error) => void) | null = null;
  protected closeHandler: (() => void) | null = null;
  protected connected = false;

  abstract connect(): Promise<void>;
  abstract disconnect(): Promise<void>;
  abstract send(message: JSONRPCRequest | JSONRPCNotification): Promise<void>;

  onMessage(handler: (message: JSONRPCMessage) => void): void {
    this.messageHandler = handler;
  }

  onError(handler: (error: Error) => void): void {
    this.errorHandler = handler;
  }

  onClose(handler: () => void): void {
    this.closeHandler = handler;
  }

  isConnected(): boolean {
    return this.connected;
  }

  protected handleMessage(data: string): void {
    if (!this.messageHandler) return;

    try {
      const message = JSON.parse(data) as JSONRPCMessage;
      this.messageHandler(message);
    } catch (error) {
      this.handleError(new Error(`Failed to parse message: ${error}`));
    }
  }

  protected handleError(error: Error): void {
    if (this.errorHandler) {
      this.errorHandler(error);
    } else {
      console.error('[MCP Transport] Unhandled error:', error);
    }
  }

  protected handleClose(): void {
    this.connected = false;
    if (this.closeHandler) {
      this.closeHandler();
    }
  }
}
