/**
 * Summarizer
 *
 * LLM-powered incremental conversation summarization.
 * Generates concise summaries of older messages that were truncated
 * from the context window. Supports incremental re-summarization
 * with watermarking.
 */

import type { Message } from '../types';
import type { SummarizerConfig, SummaryState, Tokenizer } from './types';
import { estimateTokens, getTokenizer } from './token-counter';

/** Default summary target tokens */
const DEFAULT_TARGET_TOKENS = 500;

/** Default temperature for summarization */
const DEFAULT_TEMPERATURE = 0.3;

/**
 * Summarize a set of messages using an LLM.
 *
 * If an existing summary is provided, it's prepended as context
 * for incremental summarization (watermarking pattern).
 *
 * @param messages - Messages to summarize (the "old" messages)
 * @param existingSummary - Previous summary to build upon (optional)
 * @param config - Summarizer configuration
 * @returns New summary state
 */
export async function summarizeMessages(
  messages: Message[],
  existingSummary?: SummaryState,
  config?: SummarizerConfig,
): Promise<SummaryState> {
  if (!config?.provider) {
    // No LLM available — fall back to basic summary
    return createFallbackSummary(messages, existingSummary, config?.tokenizer);
  }

  const targetTokens = config.targetTokens ?? DEFAULT_TARGET_TOKENS;
  const temperature = config.temperature ?? DEFAULT_TEMPERATURE;
  const model = config.model || 'gpt-4o';

  // Build the summarization prompt
  const messagesText = formatMessagesForSummary(messages);

  let prompt: string;
  if (existingSummary) {
    prompt = `You are summarizing a conversation that has been ongoing. Here is the existing summary of earlier parts:

---
${existingSummary.text}
---

And here are the new messages to incorporate into the summary:

---
${messagesText}
---

Create an updated, comprehensive summary that combines the existing summary with the new messages. Preserve:
- Key decisions and conclusions
- Important facts and context established
- Any commitments, tasks, or action items
- Technical details that may be referenced later
- User preferences and patterns observed

Keep the summary under ${targetTokens} tokens. Write in third person past tense.`;
  } else {
    prompt = `Summarize the following conversation history concisely. Preserve:
- Key decisions and conclusions
- Important facts and context established
- Any commitments, tasks, or action items
- Technical details that may be referenced later
- User preferences and patterns observed

---
${messagesText}
---

Keep the summary under ${targetTokens} tokens. Write in third person past tense.`;
  }

  try {
    const response = await fetch(`${config.provider.baseUrl}/responses`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.provider.apiKey}`,
        'OpenAI-Beta': 'responses=v1',
      },
      body: JSON.stringify({
        model,
        input: [{ role: 'user', content: prompt }],
        max_output_tokens: targetTokens + 200, // Buffer for model variance
        temperature,
        stream: false,
      }),
    });

    if (!response.ok) {
      console.warn(`[Summarizer] LLM call failed: ${response.status}, using fallback`);
      return createFallbackSummary(messages, existingSummary, config.tokenizer);
    }

    const data = await response.json() as {
      output_text?: string;
      output?: Array<{ type: string; content?: Array<{ type: string; text?: string }> }>;
    };

    // Extract text from response
    let summaryText = data.output_text || '';
    if (!summaryText && data.output) {
      for (const item of data.output) {
        if (item.type === 'message' && item.content) {
          for (const part of item.content) {
            if (part.type === 'output_text' && part.text) {
              summaryText += part.text;
            }
          }
        }
      }
    }

    if (!summaryText) {
      console.warn('[Summarizer] Empty LLM response, using fallback');
      return createFallbackSummary(messages, existingSummary, config.tokenizer);
    }

    // Find the last message ID for watermarking
    const lastMessageId = findLastMessageId(messages);

    return {
      text: summaryText.trim(),
      upToMessageId: lastMessageId,
      tokenCount: estimateTokens(summaryText, config.tokenizer),
    };
  } catch (error) {
    console.warn('[Summarizer] LLM call error:', error);
    return createFallbackSummary(messages, existingSummary, config.tokenizer);
  }
}

/**
 * Create a fallback summary without LLM (used when LLM is unavailable)
 */
export function createFallbackSummary(
  messages: Message[],
  existingSummary?: SummaryState,
  tokenizer?: Tokenizer,
): SummaryState {
  const tok = getTokenizer(tokenizer);

  // Extract key user messages as topics
  const userMessages = messages
    .filter(m => m.role === 'user')
    .map(m => {
      const content = typeof m.content === 'string' ? m.content : '[multimodal message]';
      return content.slice(0, 150);
    });

  const topics = userMessages.slice(0, 5);
  let text: string;

  if (existingSummary) {
    text = `${existingSummary.text}\n\nSubsequent discussion covered: ${topics.join('; ')}`;
  } else {
    text = `Previous conversation covered: ${topics.join('; ')}`;
  }

  // Truncate if too long
  if (text.length > 2000) {
    text = text.slice(0, 2000) + '...';
  }

  const lastMessageId = findLastMessageId(messages);

  return {
    text,
    upToMessageId: lastMessageId,
    tokenCount: tok.count(text),
  };
}

/**
 * Format messages into readable text for the summarization prompt
 */
function formatMessagesForSummary(messages: Message[]): string {
  const lines: string[] = [];

  for (const msg of messages) {
    const role = msg.role.charAt(0).toUpperCase() + msg.role.slice(1);
    let content: string;

    if (typeof msg.content === 'string') {
      content = msg.content;
    } else if (Array.isArray(msg.content)) {
      content = msg.content
        .map(part => {
          if (part.type === 'text' && part.text) return part.text;
          if (part.type === 'image') return '[image]';
          if (part.type === 'file') return '[file]';
          return '';
        })
        .filter(Boolean)
        .join(' ');
    } else {
      content = '[empty]';
    }

    // Truncate very long messages
    if (content.length > 1000) {
      content = content.slice(0, 1000) + '... [truncated]';
    }

    lines.push(`${role}: ${content}`);

    // Note tool calls
    if (msg.toolCalls && msg.toolCalls.length > 0) {
      const toolNames = msg.toolCalls.map(tc => tc.function?.name).filter(Boolean);
      lines.push(`  [Used tools: ${toolNames.join(', ')}]`);
    }
  }

  return lines.join('\n');
}

/**
 * Find the last message with an identifiable ID or position
 */
function findLastMessageId(messages: Message[]): string | undefined {
  // Walk backwards to find the last message with any identifying property
  for (let i = messages.length - 1; i >= 0; i--) {
    const msg = messages[i] as Message & { id?: string };
    if (msg.id) return msg.id;
    if (msg.toolCallId) return `tool:${msg.toolCallId}`;
  }
  // Fall back to message count as a watermark
  return `count:${messages.length}`;
}
