/**
 * MCP Types
 *
 * Type definitions for the Model Context Protocol (MCP).
 * Based on the MCP specification.
 */

// ============================================
// JSON-RPC Types
// ============================================

/**
 * JSON-RPC 2.0 request
 */
export interface JSONRPCRequest<T = unknown> {
  jsonrpc: '2.0';
  id: string | number;
  method: string;
  params?: T;
}

/**
 * JSON-RPC 2.0 notification (no id, no response expected)
 */
export interface JSONRPCNotification<T = unknown> {
  jsonrpc: '2.0';
  method: string;
  params?: T;
}

/**
 * JSON-RPC 2.0 success response
 */
export interface JSONRPCSuccessResponse<T = unknown> {
  jsonrpc: '2.0';
  id: string | number;
  result: T;
}

/**
 * JSON-RPC 2.0 error response
 */
export interface JSONRPCErrorResponse {
  jsonrpc: '2.0';
  id: string | number | null;
  error: {
    code: number;
    message: string;
    data?: unknown;
  };
}

export type JSONRPCResponse<T = unknown> = JSONRPCSuccessResponse<T> | JSONRPCErrorResponse;

export type JSONRPCMessage = JSONRPCRequest | JSONRPCNotification | JSONRPCResponse;

/**
 * Standard JSON-RPC error codes
 */
export const JSONRPC_ERROR_CODES = {
  PARSE_ERROR: -32700,
  INVALID_REQUEST: -32600,
  METHOD_NOT_FOUND: -32601,
  INVALID_PARAMS: -32602,
  INTERNAL_ERROR: -32603,
} as const;

// ============================================
// MCP Protocol Types
// ============================================

/**
 * MCP protocol version
 */
export const MCP_VERSION = '2024-11-05';

/**
 * Server capabilities
 */
export interface MCPServerCapabilities {
  /** Tools the server can execute */
  tools?: {
    /** Whether the server supports tool listing change notifications */
    listChanged?: boolean;
  };
  /** Resources the server can provide */
  resources?: {
    /** Whether the server supports subscribing to resource changes */
    subscribe?: boolean;
    /** Whether the server supports resource listing change notifications */
    listChanged?: boolean;
  };
  /** Prompts the server can provide */
  prompts?: {
    /** Whether the server supports prompt listing change notifications */
    listChanged?: boolean;
  };
  /** Logging capabilities */
  logging?: Record<string, never>;
  /** Experimental capabilities */
  experimental?: Record<string, unknown>;
}

/**
 * Client capabilities
 */
export interface MCPClientCapabilities {
  /** Root capabilities */
  roots?: {
    /** Whether the client supports root listing changes */
    listChanged?: boolean;
  };
  /** Sampling capabilities */
  sampling?: Record<string, never>;
  /** Experimental capabilities */
  experimental?: Record<string, unknown>;
}

/**
 * Server info
 */
export interface MCPServerInfo {
  name: string;
  version: string;
}

/**
 * Client info
 */
export interface MCPClientInfo {
  name: string;
  version: string;
}

/**
 * Initialize request params
 */
export interface MCPInitializeParams {
  protocolVersion: string;
  capabilities: MCPClientCapabilities;
  clientInfo: MCPClientInfo;
}

/**
 * Initialize response result
 */
export interface MCPInitializeResult {
  protocolVersion: string;
  capabilities: MCPServerCapabilities;
  serverInfo: MCPServerInfo;
  instructions?: string;
}

// ============================================
// MCP Tool Types
// ============================================

/**
 * JSON Schema for tool parameters
 */
export interface MCPToolInputSchema {
  type: 'object';
  properties?: Record<string, {
    type: string;
    description?: string;
    enum?: string[];
    items?: { type: string };
    default?: unknown;
    [key: string]: unknown;
  }>;
  required?: string[];
  additionalProperties?: boolean;
}

/**
 * Tool definition from MCP server
 */
export interface MCPTool {
  name: string;
  description?: string;
  inputSchema: MCPToolInputSchema;
}

/**
 * Tool list response
 */
export interface MCPToolListResult {
  tools: MCPTool[];
  nextCursor?: string;
}

/**
 * Tool call request params
 */
export interface MCPToolCallParams {
  name: string;
  arguments?: Record<string, unknown>;
}

/**
 * Content types for tool results
 */
export interface MCPTextContent {
  type: 'text';
  text: string;
}

export interface MCPImageContent {
  type: 'image';
  data: string; // base64
  mimeType: string;
}

export interface MCPResourceContent {
  type: 'resource';
  resource: {
    uri: string;
    mimeType?: string;
    text?: string;
    blob?: string; // base64
  };
}

export type MCPContent = MCPTextContent | MCPImageContent | MCPResourceContent;

/**
 * Tool call result
 */
export interface MCPToolCallResult {
  content: MCPContent[];
  isError?: boolean;
}

// ============================================
// MCP Resource Types
// ============================================

/**
 * Resource definition
 */
export interface MCPResource {
  uri: string;
  name: string;
  description?: string;
  mimeType?: string;
}

/**
 * Resource list result
 */
export interface MCPResourceListResult {
  resources: MCPResource[];
  nextCursor?: string;
}

/**
 * Resource read params
 */
export interface MCPResourceReadParams {
  uri: string;
}

/**
 * Resource read result
 */
export interface MCPResourceReadResult {
  contents: Array<{
    uri: string;
    mimeType?: string;
    text?: string;
    blob?: string; // base64
  }>;
}

// ============================================
// MCP Prompt Types
// ============================================

/**
 * Prompt argument definition
 */
export interface MCPPromptArgument {
  name: string;
  description?: string;
  required?: boolean;
}

/**
 * Prompt definition
 */
export interface MCPPrompt {
  name: string;
  description?: string;
  arguments?: MCPPromptArgument[];
}

/**
 * Prompt list result
 */
export interface MCPPromptListResult {
  prompts: MCPPrompt[];
  nextCursor?: string;
}

/**
 * Prompt get params
 */
export interface MCPPromptGetParams {
  name: string;
  arguments?: Record<string, string>;
}

/**
 * Prompt message role
 */
export type MCPPromptRole = 'user' | 'assistant';

/**
 * Prompt message
 */
export interface MCPPromptMessage {
  role: MCPPromptRole;
  content: MCPTextContent | MCPImageContent | MCPResourceContent;
}

/**
 * Prompt get result
 */
export interface MCPPromptGetResult {
  description?: string;
  messages: MCPPromptMessage[];
}

// ============================================
// MCP Notification Types
// ============================================

/**
 * Progress notification params
 */
export interface MCPProgressParams {
  progressToken: string | number;
  progress: number;
  total?: number;
}

/**
 * Log level
 */
export type MCPLogLevel = 'debug' | 'info' | 'notice' | 'warning' | 'error' | 'critical' | 'alert' | 'emergency';

/**
 * Log message params
 */
export interface MCPLogMessageParams {
  level: MCPLogLevel;
  logger?: string;
  data: unknown;
}

