// ============================================
// Transport Types
// ============================================

/**
 * MCP Transport interface
 */
export interface MCPTransport {
  /** Connect to the server */
  connect(): Promise<void>;

  /** Disconnect from the server */
  disconnect(): Promise<void>;

  /** Send a JSON-RPC message */
  send(message: JSONRPCRequest | JSONRPCNotification): Promise<void>;

  /** Set message handler */
  onMessage(handler: (message: JSONRPCMessage) => void): void;

  /** Set error handler */
  onError(handler: (error: Error) => void): void;

  /** Set close handler */
  onClose(handler: () => void): void;

  /** Check if connected */
  isConnected(): boolean;
}

/**
 * Transport configuration base
 */
export interface MCPTransportConfig {
  /** Connection timeout in ms */
  timeout?: number;
}

/**
 * Stdio transport configuration
 */
export interface MCPStdioConfig extends MCPTransportConfig {
  type: 'stdio';
  /** Command to spawn */
  command: string;
  /** Command arguments */
  args?: string[];
  /** Environment variables */
  env?: Record<string, string>;
  /** Working directory */
  cwd?: string;
}

/**
 * SSE transport configuration
 */
export interface MCPSSEConfig extends MCPTransportConfig {
  type: 'sse';
  /** SSE endpoint URL */
  url: string;
  /** HTTP headers */
  headers?: Record<string, string>;
}

export type MCPTransportType = MCPStdioConfig | MCPSSEConfig;

// ============================================
// MCP Server Configuration
// ============================================

/**
 * MCP server configuration for SAGE
 */
export interface MCPServerConfig {
  /** Unique name for this server */
  name: string;
  /** Transport configuration */
  transport: MCPTransportType;
  /** Auto-connect on startup */
  autoConnect?: boolean;
  /** Reconnect on disconnect */
  reconnect?: boolean;
  /** Reconnect delay in ms */
  reconnectDelay?: number;
  /** Max reconnect attempts */
  maxReconnectAttempts?: number;
}
