/**
 * Auth Server
 *
 * Better Auth server-side configuration.
 * Extracted from Stratus auth.ts.
 */

import type { AuthConfig, AuthUser, AuthSession } from './types';

/**
 * Create auth configuration for Better Auth
 *
 * This returns the configuration object to pass to betterAuth().
 * The consuming app should import betterAuth from 'better-auth' directly.
 *
 * @example
 * ```typescript
 * import { betterAuth } from 'better-auth';
 * import { createAuthConfig } from '@sage/core/auth';
 *
 * export const auth = betterAuth(createAuthConfig({
 *   databaseUrl: process.env.DATABASE_URL,
 *   siteUrl: process.env.SITE_URL,
 * }));
 * ```
 */
export function createAuthConfig(config: AuthConfig): Record<string, unknown> {
  const {
    databaseUrl,
    siteUrl,
    audience = 'sage',
    sessionExpiry = 60 * 60 * 24 * 7, // 7 days
    emailPassword = true,
    google,
  } = config;

  const authConfig: Record<string, unknown> = {
    database: {
      type: 'postgres',
      url: databaseUrl,
    },
    emailAndPassword: {
      enabled: emailPassword,
      requireEmailVerification: true,
    },
    session: {
      expiresIn: sessionExpiry,
      updateAge: 60 * 60 * 24, // Refresh daily
      freshAge: 60 * 5, // 5 min sensitive age
    },
    plugins: [],
    advanced: {
      cookiePrefix: 'sage-auth',
    },
  };

  // Add JWT plugin config (to be used with better-auth jwt plugin)
  const jwtConfig = {
    audience,
    issuer: siteUrl || process.env.SITE_URL || 'http://localhost:3000',
    expiresIn: 60 * 15, // 15 min JWT expiry
  };
  (authConfig as any).jwt = jwtConfig;

  // Add Google OAuth if configured
  if (google) {
    (authConfig as any).socialProviders = {
      google: {
        clientId: google.clientId,
        clientSecret: google.clientSecret,
      },
    };
  }

  return authConfig;
}

/**
 * Get user from session token
 *
 * This is a helper that should be called with the auth instance
 * from the consuming app.
 */
export async function getUserFromToken(
  auth: { api: { getSession: (opts: { headers: Headers }) => Promise<{ user: AuthUser; session: AuthSession } | null> } },
  headers: Headers
): Promise<{ user: AuthUser; session: AuthSession } | null> {
  try {
    const result = await auth.api.getSession({ headers });
    return result;
  } catch {
    return null;
  }
}

/**
 * Validate that a request is authenticated
 */
export function requireAuth<T extends { user: AuthUser; session: AuthSession }>(
  result: T | null
): T {
  if (!result) {
    throw new Error('Unauthorized');
  }
  return result;
}

/**
 * Environment variables needed for auth
 */
export const AUTH_ENV_VARS = [
  'DATABASE_URL',
  'BETTER_AUTH_SECRET',
  'SITE_URL',
  'GOOGLE_CLIENT_ID',
  'GOOGLE_CLIENT_SECRET',
] as const;

/**
 * Validate auth environment variables
 */
export function validateAuthEnv(): { valid: boolean; missing: string[] } {
  const missing: string[] = [];

  if (!process.env.DATABASE_URL) missing.push('DATABASE_URL');
  if (!process.env.BETTER_AUTH_SECRET) missing.push('BETTER_AUTH_SECRET');

  return {
    valid: missing.length === 0,
    missing,
  };
}
