/**
 * Token Counter
 *
 * Estimates token counts for messages and text.
 * Default uses a character heuristic (~90% accurate, no WASM/native deps).
 * Apps can plug in tiktoken or any custom tokenizer.
 */

import type { Message } from '../types';
import type { Tokenizer } from './types';

/**
 * Default tokenizer using character heuristic.
 * ~4 characters per token with a 10% safety buffer.
 * Avoids tiktoken WASM issues in Next.js/edge environments.
 */
export class CharacterTokenizer implements Tokenizer {
  count(text: string): number {
    if (!text) return 0;
    return Math.ceil((text.length / 4) * 1.1);
  }
}

/** Default tokenizer instance */
const defaultTokenizer = new CharacterTokenizer();

/**
 * Get the tokenizer to use (custom or default)
 */
export function getTokenizer(custom?: Tokenizer): Tokenizer {
  return custom || defaultTokenizer;
}

/**
 * Estimate tokens for a plain string
 */
export function estimateTokens(text: string, tokenizer?: Tokenizer): number {
  return getTokenizer(tokenizer).count(text);
}

/**
 * Estimate tokens for a single message, including structural overhead.
 *
 * Accounts for:
 * - Role tokens (4 per message for role + structure)
 * - String content
 * - Multimodal content arrays (text parts, images ~170 tokens each)
 * - Tool calls (function name + arguments + 10 overhead per call)
 * - Tool result messages (content + toolCallId overhead)
 */
export function estimateMessageTokens(message: Message, tokenizer?: Tokenizer): number {
  const tok = getTokenizer(tokenizer);
  const overhead = 4; // Role, message boundary, etc.

  let contentTokens = 0;

  // Handle content
  if (typeof message.content === 'string') {
    contentTokens = tok.count(message.content);
  } else if (Array.isArray(message.content)) {
    // Multimodal content parts
    for (const part of message.content) {
      if (part.type === 'text' && part.text) {
        contentTokens += tok.count(part.text);
      } else if (part.type === 'image') {
        // Conservative image token estimate
        contentTokens += 170;
      } else if (part.type === 'file') {
        // File reference token estimate
        contentTokens += 50;
      }
    }
  }

  // Handle tool calls on assistant messages
  let toolCallTokens = 0;
  if (message.toolCalls && message.toolCalls.length > 0) {
    for (const tc of message.toolCalls) {
      toolCallTokens += 10; // Per-call overhead (call_id, type, etc.)
      if (tc.function?.name) {
        toolCallTokens += tok.count(tc.function.name);
      }
      if (tc.function?.arguments) {
        toolCallTokens += tok.count(tc.function.arguments);
      }
    }
  }

  // Handle tool result message overhead
  let toolResultOverhead = 0;
  if (message.toolCallId) {
    toolResultOverhead = 5; // call_id reference + type marker
  }

  // Handle reasoning
  let reasoningTokens = 0;
  if (message.reasoning) {
    reasoningTokens = tok.count(message.reasoning);
  }

  return overhead + contentTokens + toolCallTokens + toolResultOverhead + reasoningTokens;
}

/**
 * Estimate total tokens for an array of messages
 */
export function estimateTotalTokens(messages: Message[], tokenizer?: Tokenizer): number {
  let total = 0;
  for (const msg of messages) {
    total += estimateMessageTokens(msg, tokenizer);
  }
  return total;
}

/**
 * Quick pre-check: will the messages need truncation?
 * Used to show "compacting..." UI before async summarization.
 */
export function willNeedTruncation(options: {
  messages: Message[];
  systemPromptTokens: number;
  contextWindow: number;
  maxResponseTokens: number;
  summaryTokens?: number;
  memoryTokens?: number;
  tokenizer?: Tokenizer;
}): boolean {
  const {
    messages,
    systemPromptTokens,
    contextWindow,
    maxResponseTokens,
    summaryTokens = 0,
    memoryTokens = 0,
    tokenizer,
  } = options;

  const available = contextWindow - systemPromptTokens - summaryTokens - memoryTokens - maxResponseTokens;
  const totalMessageTokens = estimateTotalTokens(messages, tokenizer);
  return totalMessageTokens > available;
}
