/**
 * MCP Manager
 *
 * Manages multiple MCP server connections and provides
 * integration with SAGE's tool registry.
 */

import type { MCPServerConfig, MCPTool, MCPToolCallResult, MCPContent } from './types';
import { MCPClient, createMCPClient, type MCPClientOptions } from './client';
import type { Tool, ToolRegistry, ToolContext } from '../tools/types';

/**
 * MCP Manager options
 */
export interface MCPManagerOptions {
  /** Client options passed to all MCP clients */
  clientOptions?: MCPClientOptions;
  /** Auto-connect to all servers on start */
  autoConnect?: boolean;
  /** Called when tools change on any server */
  onToolsChanged?: (serverName: string, tools: MCPTool[]) => void;
}

/**
 * MCP Manager
 *
 * Coordinates multiple MCP server connections and
 * integrates their tools with SAGE.
 */
export class MCPManager {
  private clients = new Map<string, MCPClient>();
  private options: MCPManagerOptions;

  constructor(options: MCPManagerOptions = {}) {
    this.options = options;
  }

  /**
   * Add an MCP server
   */
  addServer(config: MCPServerConfig): void {
    if (this.clients.has(config.name)) {
      throw new Error(`Server '${config.name}' already exists`);
    }

    const client = createMCPClient(config, {
      ...this.options.clientOptions,
      events: {
        ...this.options.clientOptions?.events,
        onToolsChanged: (tools) => {
          this.options.onToolsChanged?.(config.name, tools);
        },
      },
    });

    this.clients.set(config.name, client);
  }

  /**
   * Remove an MCP server
   */
  async removeServer(name: string): Promise<void> {
    const client = this.clients.get(name);
    if (client) {
      await client.disconnect();
      this.clients.delete(name);
    }
  }

  /**
   * Get an MCP client by name
   */
  getClient(name: string): MCPClient | undefined {
    return this.clients.get(name);
  }

  /**
   * Get all client names
   */
  getServerNames(): string[] {
    return Array.from(this.clients.keys());
  }

  /**
   * Connect to all servers
   */
  async connectAll(): Promise<void> {
    const promises = Array.from(this.clients.values()).map(async (client) => {
      try {
        await client.connect();
      } catch (error) {
        console.error(`[MCP] Failed to connect to ${client.getServerName()}:`, error);
      }
    });

    await Promise.all(promises);
  }

  /**
   * Disconnect from all servers
   */
  async disconnectAll(): Promise<void> {
    const promises = Array.from(this.clients.values()).map((client) => client.disconnect());
    await Promise.all(promises);
  }

  /**
   * Get all tools from all connected servers
   */
  async getAllTools(): Promise<Array<MCPTool & { serverName: string }>> {
    const allTools: Array<MCPTool & { serverName: string }> = [];

    for (const [name, client] of this.clients) {
      if (!client.isConnected()) continue;

      try {
        const tools = await client.listTools();
        for (const tool of tools) {
          allTools.push({ ...tool, serverName: name });
        }
      } catch (error) {
        console.warn(`[MCP] Failed to list tools from ${name}:`, error);
      }
    }

    return allTools;
  }

  /**
   * Call a tool on a specific server
   */
  async callTool(
    serverName: string,
    toolName: string,
    args?: Record<string, unknown>
  ): Promise<MCPToolCallResult> {
    const client = this.clients.get(serverName);
    if (!client) {
      throw new Error(`Server '${serverName}' not found`);
    }
    if (!client.isConnected()) {
      throw new Error(`Server '${serverName}' is not connected`);
    }

    return client.callTool(toolName, args);
  }

  /**
   * Register all MCP tools with a SAGE tool registry
   *
   * Creates wrapper tools that delegate to MCP servers.
   */
  async registerToolsWithRegistry(registry: ToolRegistry): Promise<void> {
    const allTools = await this.getAllTools();

    for (const tool of allTools) {
      const toolDef = this.createToolDefinition(tool.serverName, tool);
      registry.register(toolDef);
    }
  }

  /**
   * Create a SAGE tool definition from an MCP tool
   */
  private createToolDefinition(
    serverName: string,
    mcpTool: MCPTool
  ): Tool {
    // Create unique tool name with server prefix
    const toolName = `${serverName}__${mcpTool.name}`;

    return {
      name: toolName,
      description: mcpTool.description || `Tool from MCP server: ${serverName}`,
      // MCP schema is compatible with our JSONSchema, cast for type safety
      parameters: mcpTool.inputSchema as unknown as Tool['parameters'],
      execute: async (args: Record<string, unknown>, context: ToolContext) => {
        const result = await this.callTool(serverName, mcpTool.name, args);
        return this.formatToolResult(result);
      },
    };
  }

  /**
   * Format MCP tool result for SAGE
   */
  private formatToolResult(result: MCPToolCallResult): string {
    if (result.isError) {
      const errorContent = result.content.find((c) => c.type === 'text');
      throw new Error(errorContent?.type === 'text' ? errorContent.text : 'Tool execution failed');
    }

    // Combine all text content
    const textParts: string[] = [];
    for (const content of result.content) {
      if (content.type === 'text') {
        textParts.push(content.text);
      } else if (content.type === 'image') {
        textParts.push(`[Image: ${content.mimeType}]`);
      } else if (content.type === 'resource') {
        if (content.resource.text) {
          textParts.push(content.resource.text);
        } else {
          textParts.push(`[Resource: ${content.resource.uri}]`);
        }
      }
    }

    return textParts.join('\n');
  }
}

/**
 * Create an MCP manager
 */
export function createMCPManager(options?: MCPManagerOptions): MCPManager {
  return new MCPManager(options);
}
