/**
 * Session Management
 *
 * Handles creating and managing agentic sessions.
 */

import { randomUUID } from 'crypto';
import type { Session, SessionStatus, SageConfig } from '../types';
import type { AgentContext, AgentCallbacks } from './types';
import type { StreamStore } from '../streaming/types';
import type { ToolRegistry } from '../tools/types';
import type { SessionRepository, MessageRepository } from '../db/types';
import type { WorkingMemoryManager, ContextConfig } from '../context/types';
import { processWithToolLoop } from './loop';
import { registerSubagentTools } from './subagent';
import type { SubagentDefinition } from './subagent';

/**
 * Options for creating a session
 */
export interface CreateSessionOptions {
  conversationId: string;
  userId: string;
  systemPrompt: string;
  messages: AgentContext['messages'];
  tools: ToolRegistry;
  streamStore: StreamStore;
  config: SageConfig;
  sessionRepository?: SessionRepository;
  messageRepository?: MessageRepository;
  callbacks?: AgentCallbacks;
  workingMemory?: WorkingMemoryManager;
  contextConfig?: ContextConfig;
}

/**
 * Create and start a new agentic session
 */
export async function createSession(
  options: CreateSessionOptions
): Promise<{ sessionId: string; streamId: string; result: Promise<void> }> {
  const {
    conversationId,
    userId,
    systemPrompt,
    messages,
    tools,
    streamStore,
    config,
    sessionRepository,
    messageRepository,
    callbacks,
    workingMemory,
    contextConfig,
  } = options;

  // Generate IDs
  const sessionId = randomUUID();
  const streamId = randomUUID();

  // Create session record if repository is provided
  if (sessionRepository) {
    await sessionRepository.create({
      conversationId,
      userId,
      streamId,
    });
  }

  // Set up session metadata in stream store
  await streamStore.setMeta(streamId, {
    sessionId,
    conversationId,
    userId,
    status: 'pending',
    createdAt: Date.now(),
  });

  // Build agent context
  const context: AgentContext = {
    sessionId,
    conversationId,
    userId,
    streamId,
    systemPrompt,
    messages,
    tools,
    streamStore,
    config,
    callbacks,
    agentId: config.agent?.name || 'root',
    agentDepth: 0,
    workingMemory,
    contextConfig,
  };

  // Register subagent delegation tools on the root agent
  if (config.subagents && config.subagents.length > 0) {
    const allTools = tools.list();
    const definitions: SubagentDefinition[] = config.subagents;
    const maxAgentDepth = config.maxAgentDepth ?? 1;
    registerSubagentTools(tools, definitions, context, allTools, maxAgentDepth);
  }

  // Start processing (returns a promise that resolves when done)
  const result = processWithToolLoop(context)
    .then(async (agentResult) => {
      // Auto-extract memories after completion
      if (workingMemory && config.context?.workingMemory?.autoExtract && agentResult.content) {
        try {
          await workingMemory.extractMemories(
            userId,
            messages,
            agentResult.content,
            conversationId,
          );
        } catch (err) {
          console.warn('[SAGE] Memory extraction failed:', err);
        }
      }

      // Save assistant message to conversation history
      if (messageRepository && agentResult.content) {
        await messageRepository.saveAssistantMessage({
          conversationId,
          content: agentResult.content,
          reasoning: agentResult.reasoning,
          toolCalls: agentResult.toolCalls.length > 0 ? agentResult.toolCalls : undefined,
          inputTokens: agentResult.inputTokens,
          outputTokens: agentResult.outputTokens,
        });
      }

      // Update session as completed
      if (sessionRepository) {
        await sessionRepository.complete(sessionId, {
          accumulatedContent: agentResult.content,
          accumulatedReasoning: agentResult.reasoning,
          inputTokens: agentResult.inputTokens,
          outputTokens: agentResult.outputTokens,
        });
      }
    })
    .catch(async (error) => {
      // Update session as failed
      const errorMsg = error instanceof Error ? error.message : String(error);

      callbacks?.onError?.(error instanceof Error ? error : new Error(errorMsg));
      callbacks?.onStatusChange?.('failed');

      await streamStore.append(streamId, {
        type: 'error',
        content: errorMsg,
        timestamp: Date.now(),
        status: 'failed',
      });

      if (sessionRepository) {
        await sessionRepository.updateStatus(sessionId, 'failed', {
          error: errorMsg,
          completedAt: Date.now(),
        });
      }

      throw error;
    });

  return { sessionId, streamId, result };
}

/**
 * Build a system prompt for the agent
 */
export function buildSystemPrompt(options: {
  agentName?: string;
  basePrompt?: string;
  projectInstructions?: string;
  timezone?: string;
  hasMemoryTools?: boolean;
}): string {
  const { agentName = 'SAGE Agent', basePrompt, projectInstructions, timezone } = options;

  const now = new Date();
  const timeStr = now.toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
    timeZone: timezone,
  });
  const dateStr = now.toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric',
    timeZone: timezone,
  });

  let prompt = basePrompt || `You are ${agentName}, an intelligent AI assistant.

Current time: ${timeStr}
Current date: ${dateStr}

You have access to various tools to help users. Be helpful, accurate, and concise.

## IMPORTANT: Be Proactive with Tools

When a user asks for information you can look up, USE the appropriate tool immediately.
Don't ask clarifying questions when you can use tools to get the information.

Take action first, then ask questions only if the tools don't provide enough info.

## Tool Error Handling
- When a tool call returns an error, DO NOT retry the same tool with the same arguments.
- If a tool fails, explain briefly and suggest alternatives.

## Citations
When you use tools that return sources, cite them in your response using [1], [2], etc.`;

  if (projectInstructions) {
    prompt += `\n\n## Project Context\n${projectInstructions}`;
  }

  if (options.hasMemoryTools) {
    prompt += `\n\n## Memory Tools
You have persistent memory across conversations. Use these tools proactively:
- **remember**: Store important facts, preferences, or instructions when the user shares them
- **recall**: Search your memories about the user before answering questions that might depend on context
- **update_memory**: Correct or update existing memories when information changes
- **forget**: Delete memories when the user asks you to forget something
Always confirm memory operations to the user.`;
  }

  return prompt;
}

/**
 * Generate a unique stream ID
 */
export function generateStreamId(): string {
  return randomUUID();
}
